func (u *ForPermissionUpsertBulk) Update(set func(*ForPermissionUpsert)) *ForPermissionUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&ForPermissionUpsert{UpdateSet: update})
	}))
	return u
}

